entries[33004] = { ["name"] = "Muschelette Magnifique", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 35\nBenutzen: Stellt im Verlauf von 30 sec 2148 Gesundheit und 2934 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 hour lang 24 Angriffskraft und 14 Zaubermacht." }
