entries[33008] = { ["name"] = "Propagandamaterial der Deserteure", ["text"] = "Questgegenstand\n\"Eine Kiste mit Handzetteln, in denen Lady Jaina denunziert und die Wachen von Theramore dazu aufgerufen werden, sich den Deserteuren anzuschließen.\"" }
entries[33009] = { ["name"] = "Zartes Schreiterfleisch", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Serviert Kyle seine Mahlzeit!\n\"Kyle würde diesen saftigen Leckerbissen genießen!\"" }
entries[33010] = { ["name"] = "Gaunahs Notiz", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr könntet vielleicht hineinspähen, ohne das Siegel zu brechen...\"\n<Zum Lesen rechtsklicken>" }
entries[33012] = { ["name"] = "Terokkarflieder", ["text"] = "In Schildhand geführt\n\"Selten und erlesen... wie alle anderen auch\"" }
