entries[33070] = { ["name"] = "Raptorköder", ["text"] = "Questgegenstand\nBenutzen: Platziert den Köder auf dem Boden in der Nähe der Windmühle der Schwarzhufe.\n\"Die fast schon ranzigen Überreste vom jüngsten Jagdausflug.\"" }
