entries[33078] = { ["name"] = "Dreiwindtotem des erbarmungslosen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nRelikt Totem\nKlassen: Schamane\nBenötigt Stufe 70\nAnlegen: Eure 'Geringe Welle der Heilung' erhöht die Abhärtungswertung des Ziels 6 sec lang um 31.\n\"Zählt als Luft-, Erd-, Feuer- und Wassertotem.\"" }
entries[33079] = { ["name"] = "Murlockostüm", ["text"] = "Accountgebunden\nSpielzeug\nBenutzen: Ein Murlockostüm." }
entries[33081] = { ["name"] = "Voodooschädel", ["text"] = "Benutzen: Werft den Schädel einem freundlich gesinnten Spieler zu. Falls er Platz in seinem Rucksack hat, wird er ihn fangen!" }
