entries[33083] = { ["name"] = "Orcgrog", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 5 min (Realzeit)\nBenutzen: Wirft Schnaps und entzündet ein Feuer. (10 Sek. Abklingzeit)\n\"Das kann nur ungesund sein.\"" }
entries[33084] = { ["name"] = "Dunkelklauenguano", ["text"] = "Questgegenstand\n\"Ammoniak-, Harn-, Phosphor-, Oxal- und Kohlensäure. Mmm, die ganzen guten Sachen!\"" }
