entries[33088] = { ["name"] = "Broggs Totem", ["text"] = "Questgegenstand\nBenutzen: Entfesselt die Magie von Broggs Totem über dem Leichnam eines Aschenschweifs der Feuermähnen, Spähers der Feuermähnen oder einer Bannschuppe der Feuermähnen. (5 Sek. Abklingzeit)" }
entries[33091] = { ["name"] = "Energiegeladenes Totem", ["text"] = "Questgegenstand\nBenutzen: Bettet die Überreste eines Ogers in den Ruinen der Steinbrecher zur Ruhe. (10 Sek. Abklingzeit)\n\"Broggs fertiges Totem.\"" }
entries[33092] = { ["name"] = "Heiltrankeinspritzung", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1500 to 2500 Gesundheit wieder her. Erhöhter Effekt für Ingenieure! (1 Min Abklingzeit)" }
