entries[33095] = { ["name"] = "Banner der Steinbrecher", ["text"] = "Questgegenstand\nBenutzen: Stellt das Banner in der Nähe des Eingangs zu Onyxias Hort auf. (1 Min Abklingzeit)\n\"Dieses alte Banner ist zwar zerfleddert und muffig, dennoch zeugt es vom Stolz der Steinbrecher.\"" }
entries[33096] = { ["name"] = "Freibierkrug des Braufests", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig\nBenötigt Braufest\nBenutzen: Trinkt das Gebräu und werft den Krug!\n\"Freibier in einem spaßigen Krug zum Werfen!\"" }
