entries[33152] = { ["name"] = "Formel: Handschuhe - Überragende Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (300)\nBenötigt Hüter der Zeit\n- Ehrfürchtig\nBenutzen: Lehrt Euch, Handschuhe dauerhaft so zu verzaubern, dass sie die Beweglichkeit um 15 erhöhen.\nHandschuhe dauerhaft verzaubern, sodass die Beweglichkeit um 15 erhöht wird." }
