entries[33154] = { ["name"] = "Gruselkürbis", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nRechtsklicken, um Euren Gruselkürbis zu beschwören und freizugeben." }
