entries[33157] = { ["name"] = "Vorlage: Sternschnuppe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (360)\nBenötigt Unteres Viertel\n- Respektvoll\nBenutzen: Lehrt Euch das Schleifen einer Sternschnuppe.\nSternschnuppe\nWird beim Aufheben gebunden\nEinzigartig anlegbar\n+18 Ausdauer\nBenötigt Juwelenschleifen (360)\n\"Am besten für einen blauen Sockel geeignet. Der Gegenstand wird durch das Sockeln dieses Edelsteins seelengebunden.\"\nBenötigt Stern der Elune" }
