entries[33163] = { ["name"] = "Zeppelinfracht", ["text"] = "Questgegenstand\n\"Scheint den Absturz unversehrt überstanden zu haben... zum größten Teil.\"" }
entries[33164] = { ["name"] = "Immerbrandfackeln", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schleudert eine Immerbrandfackel bis zu 20 Meter weit und zündet damit einen Pestkessel an. Kann nur in Halgrind verwendet werden.\n\"Wie kommt es, dass die Dinger nicht aufhören, zu brennen? Es kann nur Magie sein!\"" }
entries[33165] = { ["name"] = "Formel: Waffe - Große Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (350)\nBenötigt Das Violette Auge\n- Ehrfürchtig\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie die Beweglichkeit um 20 erhöhen. Erfordert einen Gegenstand der Stufe 35 oder höher.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass sie die Beweglichkeit um 20 erhöht. Erfordert einen Gegenstand der Stufe 35 oder höher." }
entries[33166] = { ["name"] = "Pagles Fischpaste, extra stark", ["text"] = "Questgegenstand\nBenutzen: Schmiert Euch vollständig mit der Paste ein und bereitet Euch auf die Begegnung mit einigen Meereswesen vor. (5 Min Abklingzeit)\n\"Ein Glas mit der ranzigsten, aus Fischabfällen hergestellten Paste, die Ihr je gesehen habt.\"" }
entries[33173] = { ["name"] = "Zornstahlschultern", ["text"] = "Wird beim Anlegen gebunden\nSchulter Platte\n873 Rüstung\n+32 Stärke\n+12 Ausdauer\n\nGelber Sockel\nGelber Sockel\nSockelbonus: +3 Kritische Trefferwertung\n\nHaltbarkeit 80 / 80\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 17.\nAnlegen: Erhöht die Trefferwertung um 9.\n\nBrennender Zorn (0/4)\nBenötigt Schmiedekunst (350) Zornstahlbrustplatte\nZornstahlhelm\nZornstahlhandschuhe\nZornstahlschultern\n(2) Set : Erhöht Eure Trefferwertung um 20." }
