entries[33332] = { ["name"] = "Emaillierte Scheibe des Mojo", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n5400 Rüstung\n141 Blocken\n+24 Ausdauer\n+17 Intelligenz\n\nGelber Sockel\nSockelbonus: Alle 5 Sek. 1 Mana\n\nHaltbarkeit 120 / 120\nBenötigt Stufe 70\nAnlegen: Erhöht die Zaubermacht um 29.\nAnlegen: Stellt alle 5 Sek. 9 Mana wieder her." }
entries[33333] = { ["name"] = "Kharmaas Tuch der Hoffnung", ["text"] = "Wird beim Aufheben gebunden\nRücken\n114 Rüstung\n+34 Ausdauer\n+15 Intelligenz\nBenötigt Stufe 70\nAnlegen: Erhöht Eure Abhärtungswertung um 23.\nAnlegen: Erhöht die Zaubermacht um 27.\nAnlegen: Stellt alle 5 Sek. 8 Mana wieder her.\n\"Alles passiert aus einem bestimmten Grund\"" }
entries[33334] = { ["name"] = "Fetisch der wilden Götter", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+24 Ausdauer\n+17 Intelligenz\nBenötigt Stufe 70\nAnlegen: Erhöht die Tempowertung um 17.\nAnlegen: Erhöht die Zaubermacht um 37." }
entries[33335] = { ["name"] = "Rauchsignal des Kanoniers", ["text"] = "Questgegenstand\nBenutzen: Markiert eine Kanone der Allianz, die auf die provisorische Mauer am Verlassenen Strand montiert ist, mit einem Rauchsignal. (5 Sek. Abklingzeit)" }
entries[33336] = { ["name"] = "Handfernrohr des Unteroffiziers", ["text"] = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\nBenutzen: Beobachtet Entlegenes aus der Ferne.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[33337] = { ["name"] = "Riesige Giftdrüse", ["text"] = "Questgegenstand" }
entries[33339] = { ["name"] = "Vrykulrolle des Aufstiegs", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beim Scheiterhaufen des Thans in Skorn aufhängen, um Halfdan das Eisherz herauszufordern. (5 Sek. Abklingzeit)\n\"Eine bemalte Drachenhaut, auf der ein geheimnisvolles Vrykulritual dargestellt wird.\"" }
entries[33340] = { ["name"] = "Emblem der Winterhufe", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ruft einen Helden der Winterhufe herbei. Kann nur in Skorn und nicht im Kampf verwendet werden. Durch Rechtsklick auf das Emblem kann der Held wieder fortgeschickt werden. (5 Sek. Abklingzeit)" }
entries[33341] = { ["name"] = "Fernglas des Helden", ["text"] = "Herbeigezauberter Gegenstand\nQuestgegenstand\nEinzigartig\nBenutzen: Beobachtet Entlegenes aus der Ferne.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[33342] = { ["name"] = "Die Machete des Helden", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Zerstückelt einen Leichnam eines Vrykul der Winterskorn." }
entries[33343] = { ["name"] = "Fackel des Helden", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Steckt das Langhaus und die Baracken von innen heraus in Brand." }
entries[33344] = { ["name"] = "Leuchtsignal des Helden", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ihr erhaltet ein Leuchtsignal, um damit die Spitze des Turmes von Skorn zu markieren, die Reichweite zum Zielen beträgt bis zu 90 Meter. Sobald der Turm markiert ist, wird ein Luftangriff auf den Turm und seine Zauberer gestartet." }
entries[33345] = { ["name"] = "Vrykulrolle des Aufstiegs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 68\n\"Eine bemalte Drachenhaut, auf der ein geheimnisvolles Vrykulritual dargestellt wird.\"" }
