entries[33852] = { ["name"] = "Kochtopf", ["text"] = "Questgegenstand\nBenötigt Kochkunst (275)\nBenutzen: Bereitet mit 2 Rippchen der Mok'Nathal und 1 Knusperschlange Dämonenragout Surprise zu.\n\"Erfordert den glimmenden Leichnam eines abyssischen Flammenbringers.\"" }
entries[33853] = { ["name"] = "Vorherrschaftband des Verteidigers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+31 Ausdauer\n+15 Intelligenz\nBenötigt Stufe 70\nAnlegen: Erhöht Eure Abhärtungswertung um 22.\nAnlegen: Erhöht die Zaubermacht um 33.\nAnlegen: Erhöht Eure Zauberdurchschlagskraft um 14." }
entries[33854] = { ["name"] = "Unidentifizierbares Auge", ["text"] = "\"Möglicherweise gehörte es mal einem Tier, vielleicht aber auch nicht.\"" }
entries[33855] = { ["name"] = "Angelaufener Silberring", ["text"] = "Finger\n\"Der Ring hat auch schon bessere Zeiten erlebt.\"" }
entries[33856] = { ["name"] = "Liste mit Zutaten", ["text"] = "\"Blut- und Wasserflecken haben die Liste unlesbar gemacht.\"" }
entries[33857] = { ["name"] = "Kiste mit Fleisch", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält hauptsächlich Fleisch und was sonst noch so greifbar war.\"\n<Zum Öffnen rechtsklicken>" }
entries[33858] = { ["name"] = "Aeonus' Stundenglas", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Sand fließt tatsächlich aufwärts!\"" }
entries[33859] = { ["name"] = "Warpzweigsplitter", ["text"] = "Questgegenstand\nEinzigartig\n\"Es ist kaum zu glauben, dass die Druiden aus diesem kleinen Holzstück ein riesiges Urtum züchten wollen.\"" }
entries[33860] = { ["name"] = "Pathaleons Projektionsgerät", ["text"] = "Questgegenstand\nEinzigartig\n\"Damit kann er sein Abbild also überall hin projizieren!\"" }
entries[33861] = { ["name"] = "Horizontiss' Schriftrolle", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr seid nicht in der Lage, die Schriftzeichen zu entziffern. Tatsächlich schmerzt Euer Kopf schon vom bloßen Hingucken.\"" }
