entries[33865] = { ["name"] = "Hexerstecken der Amani", ["text"] = "Zul'Aman\nBenutzen: Entfernt die Verhexung der Amani von einem Urwaldfrosch in Zul'Aman.\n\"Der Anti-Hexxor Eures Vertrauens, Mann.\"" }
entries[33866] = { ["name"] = "Sturmkoteletts", ["text"] = "Benötigt Stufe 55\nBenutzen: Lädt Euch mit Energie auf und schockt für die nächsten 30 min gelegentlich nahe Gegner mit Blitzen. (10s Abklingzeit)" }
entries[33867] = { ["name"] = "Gebratene Blutflosse", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt im Verlauf von 30 sec 4320 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 30 min lang einen um 8 erhöhten Widerstand gegen alle Arten von Magie." }
entries[33868] = { ["name"] = "Braufeststiefel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFüße\nBraufesttracht (0/3)\nBraufesttracht\nBraufestdirndl\nBraufeststiefel\nBraufestschuhe\nLila Braufesthut\nGrüner Braufesthut\nBrauner Braufesthut\nBlauer Braufesthut\n(3) Set : Gesamte Brauchfesttracht" }
entries[33869] = { ["name"] = "Rezept: Gebratene Blutflosse", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (300)\nBenutzen: Lehrt Euch, wie man gebratene Blutflossen zubereitet.\nGebratene Blutflosse\nBenötigt Stufe 55\nBenutzen: Stellt im Verlauf von 30 sec 4320 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 30 min lang einen um 8 erhöhten Widerstand gegen alle Arten von Magie.\nBenötigt Blutflossenwels" }
entries[33870] = { ["name"] = "Rezept: Schädelfischsuppe", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (325)\nBenutzen: Lehrt Euch, wie man Schädelfischsuppe zubereitet.\nSchädelfischsuppe\nBenötigt Stufe 65\nBenutzen: Stellt im Verlauf von 30 sec insgesamt 7200 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Trinken verbringt, werdet Ihr erleuchtet und erhaltet 30 min lang 20 kritische Trefferwertung und Willenskraft.\nBenötigt Mondschädelfisch" }
entries[33871] = { ["name"] = "Rezept: Sturmkoteletts", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (300)\nBenutzen: Lehrt Euch, wie man Sturmkoteletts zubereitet.\nSturmkoteletts\nBenötigt Stufe 55\nBenutzen: Lädt Euch mit Energie auf und schockt für die nächsten 30 min gelegentlich nahe Gegner mit Blitzen. (10s Abklingzeit)\nBenötigt Grollhuffleisch , Zitteraal" }
entries[33872] = { ["name"] = "Feuriger Würztalbuk", ["text"] = "Benötigt Stufe 65\nBenutzen: Stellt im Verlauf von 30 sec 7500 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 30 min lang 20 Trefferwertung und Willenskraft." }
entries[33873] = { ["name"] = "Rezept: Feuriger Würztalbuk", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (325)\nBenutzen: Lehrt Euch, wie man einen feurigen Würztalbuk zubereitet.\nFeuriger Würztalbuk\nBenötigt Stufe 65\nBenutzen: Stellt im Verlauf von 30 sec 7500 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 30 min lang 20 Trefferwertung und Willenskraft.\nBenötigt Talbukwildbret" }
entries[33874] = { ["name"] = "Kiblers Häppchen", ["text"] = "Benötigt Stufe 55\nBenutzen: Erhöht die Stärke und Ausdauer Eures Begleiters um 20. Hält 1 hour lang an.\n\"Tiere lieben es! Von führenden Jägern empfohlen.\"" }
