entries[33925] = { ["name"] = "Rezept: Köstlicher Schokoladenkuchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (1)\nBenutzen: Lehrt Euch, wie man einen köstlichen Schokoladenkuchen backt.\nKöstlicher Schokoladenkuchen\nBenutzen: Wenn Ihr mindestens 5 Sekunden lang mit Essen verbringt, werdet Ihr 1 hour lang sehr glücklich.\nBenötigt Herkömmliches Mehl (8), Eiskalte Milch (4), Milde Gewürze (4), Kleines Ei (8), Fläschchen Sturmwinder Goldtropfen , Maguskönigskraut (3)" }
