entries[33954] = { ["name"] = "Pläne: Hammer der rechtschaffenen Macht", ["text"] = "Benötigt Schmiedekunst (365)\nBenutzen: Lehrt Euch die Herstellung eines Hammers der rechtschaffenen Macht.\nHammer der rechtschaffenen Macht\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n94 - 186 Schaden Tempo 2.10\n(66.67 Schaden pro Sekunde)\n+55 Ausdauer\n+37 Intelligenz\nHaltbarkeit 120 / 120\nBenötigt Stufe 70\nErhöht die Angriffskraft um 165 nur in Katzen-, Bären-, Terrorbären- und Mondkingestalt.\nAnlegen: Erhöht die Zaubermacht um 168.\nAnlegen: Stellt alle 5 Sek. 19 Mana wieder her.\nBenötigt Khoriumbarren (16), Teufelsstahlbarren (12), Urmacht (6), Urnether (2)" }
